    // The printer tools check the shape here. How many printers, and which
    // sizes, are answered by the printer session with errors of their own,
    // because those answers are what the model says next -- so a list of
    // thirty printers passes here and is refused there as too many. A nozzle
    // of null or 0 is how the model leaves it unsaid, and means that.
    const auto valid_nozzle = [&arguments] {
        return !arguments.contains("nozzle") || arguments["nozzle"].is_null() ||
               (arguments["nozzle"].is_number() && arguments["nozzle"].get<double>() >= 0. && arguments["nozzle"].get<double>() <= 5.);
    };

    if (definition.handler == ToolHandler::PrinterIdentify) {
        if (!has_only(arguments, {"catalogIds", "nozzle"}) || !arguments.contains("catalogIds") || !valid_nozzle())
            return false;
        const json& ids = arguments["catalogIds"];
        if (!ids.is_array() || ids.empty() || ids.size() > kToolListLimit)
            return false;
        return std::all_of(ids.begin(), ids.end(), [](const json& id) {
            return id.is_string() && !id.get_ref<const std::string&>().empty() && id.get_ref<const std::string&>().size() <= kToolLabelLimit;
        });
    }

    // printer_change names the saved printer it changes; the connection tools
    // act on the one the conversation is about, which the model would
    // otherwise confuse with a printer's name on the network.
    const auto names_printer = [&arguments] {
        return arguments.contains("printerName") && arguments["printerName"].is_string() && optional_text(arguments, "printerName") &&
               !arguments["printerName"].get_ref<const std::string&>().empty();
    };
    if (definition.handler == ToolHandler::PrinterManualSetup || definition.handler == ToolHandler::PrinterSetupFinish ||
        definition.handler == ToolHandler::PrinterConnectionStatus || definition.handler == ToolHandler::PrinterManualConnection)
        return arguments.empty();
    if (definition.handler == ToolHandler::PrinterAdd)
        return has_only(arguments, {"catalogId", "nozzle"}) && arguments.contains("catalogId") && optional_text(arguments, "catalogId") &&
               valid_nozzle();
    if (definition.handler == ToolHandler::PrinterConnect)
        return has_only(arguments, {"deviceId", "hostType", "address"}) && optional_text(arguments, "deviceId") && optional_text(arguments, "address") &&
               (!arguments.contains("hostType") || arguments["hostType"] == "moonraker" || arguments["hostType"] == "octoprint");

    if (definition.handler == ToolHandler::PrinterChange) {
        if (!has_only(arguments, {"printerName", "nozzle", "spools"}) || !names_printer() || !valid_nozzle())
