        m_opened                     = true;
        const std::string message_id = m_host.post_opening(text);
        for (json& entry : m_blocks)
            if (entry.value("afterMessageId", std::string()).empty())
                entry["afterMessageId"] = message_id;
        m_host.session_changed();
        return true;
