#!/usr/bin/env python3
"""Forwards POST /v1/responses to api.openai.com and logs what the model saw and did.

Logs, per request: the newest user message and tool outputs in the request, and
every completed output item (function calls with their arguments, assistant
text) from the streamed response. Never logs headers, so the API key stays out.
"""
import http.client, http.server, json, sys, time

LOG = open(sys.argv[2], "a", buffering=1)


def log(kind, payload):
    LOG.write(json.dumps({"t": time.strftime("%H:%M:%S"), "kind": kind, **payload}) + "\n")


class Proxy(http.server.BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def do_POST(self):
        body = self.rfile.read(int(self.headers.get("Content-Length", 0)))
        try:
            request = json.loads(body)
            items = request.get("input", [])
            # The tail of the conversation since the model last spoke.
            tail = []
            for item in reversed(items):
                if item.get("role") == "assistant" or item.get("type") == "function_call":
                    break
                tail.append(item)
            log("request", {"tools": [t.get("name") for t in request.get("tools", [])], "tail": list(reversed(tail))})
        except Exception as error:  # a malformed body is still forwarded
            log("request_unparsed", {"error": str(error)})

        upstream = http.client.HTTPSConnection("api.openai.com", timeout=300)
        headers = {k: v for k, v in self.headers.items() if k.lower() not in ("host", "content-length", "accept-encoding")}
        upstream.request("POST", self.path, body=body, headers=headers)
        response = upstream.getresponse()
        self.send_response(response.status)
        for k, v in response.getheaders():
            if k.lower() not in ("transfer-encoding", "content-length", "connection", "content-encoding"):
                self.send_header(k, v)
        self.send_header("Transfer-Encoding", "chunked")
        self.send_header("Connection", "close")
        self.end_headers()
        buffer = b""
        while True:
            chunk = response.read1(65536)
            if not chunk:
                break
            self.wfile.write(b"%x\r\n%s\r\n" % (len(chunk), chunk))
            self.wfile.flush()
            buffer += chunk
            while b"\n" in buffer:
                line, buffer = buffer.split(b"\n", 1)
                if line.startswith(b"data: "):
                    try:
                        event = json.loads(line[6:])
                    except ValueError:
                        continue
                    if event.get("type") == "response.output_item.done":
                        item = event.get("item", {})
                        if item.get("type") == "function_call":
                            log("tool_call", {"name": item.get("name"), "arguments": item.get("arguments")})
                        elif item.get("type") == "message":
                            text = "".join(c.get("text", "") for c in item.get("content", []))
                            log("assistant", {"text": text})
        if response.status != 200:
            log("http_error", {"status": response.status, "body": buffer.decode("utf-8", "replace")[:2000]})
        self.wfile.write(b"0\r\n\r\n")
        self.wfile.flush()

    def log_message(self, *args):
        pass


http.server.ThreadingHTTPServer(("127.0.0.1", int(sys.argv[1])), Proxy).serve_forever()

